/bin/bash -lc "node --input-type=module <<'EOF'
import { createServer } from './src/server.js';
const s=createServer({projectAdmins:{demo:['alice']},baseUrl:'http://test'}); await new Promise(r=>s.listen(0,r)); const u="'`http://127.0.0.1:${s.address().port}`;
const h={Authorization:'"'Bearer alice','Content-Type':'application/json','Idempotency-Key':'live-1'};
const a=await fetch("'`${u}/api/projects/demo/invites`,{method:'"'POST',headers:h,body:JSON.stringify({email:'live@example.com',role:'editor'})}); const aj=await a.json();
const b=await fetch("'`${u}/api/projects/demo/invites`,{method:'"'POST',headers:h,body:JSON.stringify({email:'changed@example.com',role:'viewer'})}); const bj=await b.json();
const bad=await fetch("'`${u}/api/projects/demo/invites`,{method:'"'POST',headers:{...h,'Idempotency-Key':'bad'},body:JSON.stringify({email:'not-an-email',role:'viewer'})});
const page=await fetch(u+'/');
console.log(JSON.stringify({created:a.status, retry:b.status, same:JSON.stringify(aj)===JSON.stringify(bj), role:aj.role, bad:bad.status, page:page.status, hasForm:(await page.text()).includes('invite-form')})); s.close();
EOF
node .agent-input/product-acceptance/scripts/accept-check.js --root . --strict --runtime-verified || true"

